import java.util.List;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.geometry.euclidean.oned.Interval;
import org.apache.commons.math3.geometry.euclidean.oned.IntervalsSet;
import org.apache.commons.math3.geometry.euclidean.oned.Vector1D;
import org.apache.commons.math3.geometry.euclidean.threed.IntervalsSet;
import org.apache.commons.math3.geometry.euclidean.threed.Line;
import org.apache.commons.math3.geometry.euclidean.threed.SubLine;
import org.apache.commons.math3.geometry.euclidean.threed.Vector3D;
import org.apache.commons.math3.geometry.partitioning.Region.Location;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for SubLine.getSegments().
 */
public class SubLine_getSegments_TriageGen1Test {

    private static final Line LINE = new Line(Vector3D.PLUS_ONE, Vector3D.PLUS_ONE.add(new Vector3D(1, 0, 0)));

    @Test
    public void testGetSegmentsWithEmptyIntervals() {
        // Arrange: An empty IntervalsSet should result in an empty list of segments
        IntervalsSet emptyIntervals = IntervalsSet.EMPTY;
        SubLine subLine = new SubLine(LINE, emptyIntervals);

        // Act
        List<Segment> segments = subLine.getSegments();

        // Assert
        assertNotNull(segments);
        assertTrue(segments.isEmpty());
    }

    @Test
    public void testGetSegmentsWithSingleInterval() {
        // Arrange: One interval [0.5, 1.5]
        IntervalsSet intervals = IntervalsSet.EMPTY.add(0.5, 1.5);
        SubLine subLine = new SubLine(LINE, intervals);

        // Act
        List<Segment> segments = subLine.getSegments();

        // Assert
        assertEquals(1, segments.size());
        Segment segment = segments.get(0);

        // Expected start/end points: line.toSpace(0.5) and line.toSpace(1.5)
        Vector3D expectedStart = LINE.toSpace(new Vector1D(0.5));
        Vector3D expectedEnd = LINE.toSpace(new Vector1D(1.5));

        assertEquals(expectedStart, segment.getStart());
        assertEquals(expectedEnd, segment.getEnd());
        assertEquals(LINE, segment.getLine());
    }

    @Test
    public void testGetSegmentsWithMultipleIntervals() {
        // Arrange: Multiple non-overlapping intervals
        IntervalsSet intervals = IntervalsSet.EMPTY.add(0.0, 1.0).add(2.0, 3.0);
        SubLine subLine = new SubLine(LINE, intervals);

        // Act
        List<Segment> segments = subLine.getSegments();

        // Assert
        assertEquals(2, segments.size());

        // First segment check
        assertEquals(LINE.toSpace(new Vector1D(0.0)), segments.get(0).getStart());
        assertEquals(LINE.toSpace(new Vector1D(1.0)), segments.get(0).getEnd());

        // Second segment check
        assertEquals(LINE.toSpace(new Vector1D(2.0)), segments.get(1).getStart());
        assertEquals(LINE.toSpace(new Vector1D(3.0)), segments.get(1).getEnd());
    }

    /**
     * Helper class to simulate Vector1D if not directly accessible or needed for the logic.
     * Since the original code uses new Vector1D(double), we assume it's a simple wrapper.
     */
    private static class Vector1D extends org.apache.commons.math3.geometry.euclidean.threed.Vector3D {
        protected Vector1D(double d) {
            super(d, 0, 0);
        }

        // If the actual library uses a different Vector1D, 
        // this test assumes the logic is mapping a scalar to a 3D coordinate.
        // Given the context of SubLine, it's likely treating the scalar as the 'd' parameter of the line.
    }
}

